package io.github.rubixhacker.harness.performance

import okio.ByteString.Companion.decodeBase64

/**
 * The checked-in `docs/research/performance-manifest-v1.json` bytes, so the frozen digest
 * check can be replayed without a filesystem.
 */
internal object CheckedInManifest {
    private val chunks: List<String> = listOf(
        "",
        "",
        "",
        "",
        "",
        "",
    )

    val bytes: ByteArray by lazy { chunks.joinToString("").decodeBase64()!!.toByteArray() }
}
